<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:12px;color:#1e293b;margin:25px}.center{text-align:center}.line{border-top:1px dashed #94a3b8;margin:12px 0}.right{text-align:right}.total{font-size:15px;font-weight:bold}.pending{color:#b45309}</style></head><body><div class="center"><h2 style="margin:0">{{ $order->store->name }}</h2><p>Customer order receipt</p><p>{{ $order->created_at->format('d M Y, h:i A') }}</p></div><div class="line"></div><table width="100%"><tr><td>Order no.</td><td class="right"><strong>{{ $order->order_number }}</strong></td></tr><tr><td>Customer</td><td class="right">{{ $order->customer_name }}</td></tr><tr><td>Payment</td><td class="right pending"><strong>{{ strtoupper($order->payment_status ?? 'pending') }}</strong></td></tr></table><div class="line"></div><table width="100%">@foreach($order->items as $item)<tr><td style="padding:5px 0">{{ $item->product_name }} × {{ $item->quantity }}</td><td class="right">₹{{ number_format($item->total, 2) }}</td></tr>@endforeach</table><div class="line"></div><table width="100%" class="total"><tr><td>Total</td><td class="right">₹{{ number_format($order->grand_total, 2) }}</td></tr></table><p class="center" style="margin-top:25px">Thank you for your order!</p></body></html>
